test.source:

String single() {
  var name = 'John'
  return name
}

String interp(Int id) {
  var user = 'u$id'
  return "Hello ${user}"
}

String multiline() {
  var text = '''
Line 1
Line 2'''
  return text
}

String raw() {
  return r'C:\temp\file.txt'
}

String adjacent() {
  return "Hello "
      "World"
}

run() {
  print(single())
  print(interp(7))
  print(multiline())
  print(raw())
  print(adjacent())
}
